package arrya_basic.practice;

public class UpparcaseArray {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

   String[] names = {"maruthi","N","sony","N","nagaraju","E"};
   
   System.out.println("Array Elements in uppercase==");
   
 
	for (int i = 0; i < names.length; i++) {
		System.out.println(names[i].toLowerCase());
	}
	}
}